On.styles = [Ig, bp`
      .widget-container {
        border: 1px solid var(--iso-border);
        border-radius: var(--iso-radius);
        overflow: hidden;
        background: var(--iso-bg);
      }

      .controls {
        padding: var(--iso-spacing-lg);
        display: flex;
        flex-direction: column;
        gap: var(--iso-spacing-md);
      }

      .row {
        display: flex;
        align-items: center;
        gap: var(--iso-spacing-lg);
        flex-wrap: wrap;
      }

      .actions {
        display: flex;
        gap: var(--iso-spacing-sm);
        justify-content: flex-start;
      }

      button {
        padding: var(--iso-spacing-sm) var(--iso-spacing-lg);
        border: none;
        border-radius: var(--iso-radius);
        font-size: var(--iso-font-size);
        font-family: var(--iso-font);
        cursor: pointer;
        transition: background 0.15s;
      }

      .btn-primary {
        background: var(--iso-primary);
        color: white;
      }

      .btn-primary:hover:not(:disabled) {
        background: var(--iso-primary-hover);
      }

      .btn-primary:disabled {
        opacity: 0.5;
        cursor: not-allowed;
      }

      .btn-secondary {
        background: var(--iso-bg-hover);
        color: var(--iso-text);
        border: 1px solid var(--iso-border);
      }

      .btn-secondary:hover {
        background: var(--iso-border);
      }

      /* ── Multi-slot styles ──────────────────────────────────────────────── */

      .criterion-rows {
        display: flex;
        flex-direction: column;
        gap: var(--iso-spacing-md);
      }

      /* Card style only when several slots are visible */
      .criterion-row.multi {
        background: var(--iso-bg-hover);
        border: 1px solid var(--iso-border);
        border-radius: var(--iso-radius);
        padding: var(--iso-spacing-md);
        display: flex;
        flex-direction: column;
        gap: var(--iso-spacing-sm);
      }

      /* Single-slot: keep the flat look (no card, no header) */
      .criterion-row.single {
        display: flex;
        flex-direction: column;
        gap: var(--iso-spacing-md);
      }

      .criterion-header {
        display: flex;
        align-items: center;
        gap: var(--iso-spacing-sm);
      }

      .color-dot {
        width: 10px;
        height: 10px;
        border-radius: 50%;
        flex-shrink: 0;
      }

      .criterion-label {
        flex: 1;
        font-size: var(--iso-font-size-sm);
        font-weight: 600;
        color: var(--iso-text-secondary);
      }

      .btn-remove-slot {
        background: none;
        border: none;
        cursor: pointer;
        color: var(--iso-text-secondary);
        font-size: 14px;
        padding: 2px 6px;
        border-radius: var(--iso-radius-sm);
        line-height: 1;
        font-family: var(--iso-font);
        transition: all 0.15s;
      }

      .btn-remove-slot:hover {
        background: var(--iso-bg-hover);
        color: var(--iso-danger);
      }

      .btn-add-slot {
        width: 100%;
        padding: var(--iso-spacing-sm) var(--iso-spacing-md);
        border: 1.5px dashed var(--iso-border);
        border-radius: var(--iso-radius);
        background: transparent;
        color: var(--iso-text-secondary);
        font-size: var(--iso-font-size-sm);
        font-family: var(--iso-font);
        cursor: pointer;
        text-align: center;
        transition: all 0.15s;
      }

      .btn-add-slot:hover {
        border-color: var(--iso-primary);
        color: var(--iso-primary);
        background: rgba(66, 133, 244, 0.04);
      }

      /* ── Combine mode toggle ────────────────────────────────────────────── */

      .combine-toggle {
        display: flex;
        align-items: center;
        gap: var(--iso-spacing-sm);
        flex-wrap: wrap;
      }

      .combine-toggle-label {
        font-size: var(--iso-font-size-sm);
        color: var(--iso-text-secondary);
        white-space: nowrap;
      }

      .combine-group {
        display: flex;
        border: 1px solid var(--iso-border);
        border-radius: var(--iso-radius);
        overflow: hidden;
      }

      .combine-btn {
        padding: var(--iso-spacing-xs) var(--iso-spacing-md);
        background: var(--iso-bg);
        border: none;
        border-radius: 0;
        font-size: var(--iso-font-size-sm);
        font-family: var(--iso-font);
        cursor: pointer;
        color: var(--iso-text);
        transition: all 0.15s;
        line-height: 1.4;
      }

      .combine-btn:first-child {
        border-right: 1px solid var(--iso-border);
      }

      .combine-btn.active {
        background: var(--iso-primary);
        color: white;
      }

      .combine-btn:hover:not(.active) {
        background: var(--iso-bg-hover);
      }

      /* ── Widget header (collapse toggle) ──────────────────────────────── */

      .widget-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: var(--iso-spacing-sm) var(--iso-spacing-lg);
        cursor: pointer;
        user-select: none;
        border-bottom: 1px solid var(--iso-border);
        transition: background 0.15s;
      }

      .widget-header:hover {
        background: var(--iso-bg-hover);
      }

      .widget-title {
        font-size: var(--iso-font-size);
        font-weight: 600;
        color: var(--iso-text);
      }

      .widget-chevron {
        width: 16px;
        height: 16px;
        color: var(--iso-text-secondary);
        transition: transform 0.2s ease;
        flex-shrink: 0;
      }

      :host([collapsed]) .widget-chevron {
        transform: rotate(-90deg);
      }

      .widget-body {
        display: block;
      }

      :host([collapsed]) .widget-body {
        display: none;
      }

      :host([collapsed]) .widget-header {
        border-bottom: none;
      }

      /* ── Map & messages ─────────────────────────────────────────────────── */

      .map-container {
        width: 100%;
        position: relative;
      }

      .error-msg {
        color: var(--iso-danger);
        font-size: var(--iso-font-size-sm);
        padding: 0 var(--iso-spacing-lg);
        padding-bottom: var(--iso-spacing-sm);
      }

      .warning-msg {
        color: #b45309;
        background: #fffbeb;
        border-top: 1px solid #fde68a;
        font-size: var(--iso-font-size-sm);
        padding: var(--iso-spacing-sm) var(--iso-spacing-lg);
      }
    `];
